request_examples.content:
{

    "SyncOtherMachine": 2, // 消息不同步至发送方

    "To_Account": [ // 目标账号列表

        "bonnie",

        "rong"

    ],

    "MsgSeq": 28360, // 消息序列号

    "MsgRandom": 19901224, // 消息随机数

    "MsgBody": [ // 消息

        {

            "MsgType": "TIMTextElem", // 消息类型，TIMTextElem为文本消息

            "MsgContent": {

                "Text": "hi, beauty" // 消息文本

            }

        }

    ],

    "CloudCustomData": "your cloud custom data"

}

{

    "SyncOtherMachine": 1, // 消息同步至发送方

    "From_Account": "dave",

    "To_Account": [

        "bonnie",

        "rong"

    ],

    "MsgSeq": 28360, // 消息序列号

    "MsgRandom": 19901224, // 消息随机数

    "MsgBody": [

        {

            "MsgType": "TIMTextElem",

            "MsgContent": {

                "Text": "hi, beauty"

            }

        }

    ],

    "CloudCustomData": "your cloud custom data",

    "SendMsgControl": ["NoUnread","NoLastMsg","WithMuteNotifications"],

    "OfflinePushInfo": {

        "PushFlag": 0,

        "Desc": "离线推送内容",

        "Ext": "这是透传的内容",

        "AndroidInfo": {

            "Sound": "shake" //Android 系统通知铃声文件名，详情见“消息格式描述”。

        },

        "ApnsInfo": {

            "Sound": "apns.mp3", // iOS 系统通知铃声文件名，详情见“消息格式描述”。

            "BadgeMode": 1, // 这个字段缺省或者为 0 表示需要计数，为 1 表示本条消息不需要计数，即右上角图标数字不增加

            "Title":"apns title", // apns title

            "SubTitle":"apns subtitle", // apns subtitle

            "Image":"www.image.com" // image url

        }

    }

}

